const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const point = ee.Geometry.Point(-1.187011, 29.135547);
    const geometry = point.buffer(1000); // 1km buffer around the point

    const startDate1 = '2024-08-12';
    const endDate1 = '2024-08-31'; // End of August
    const startDate2 = '2024-09-29';
    const endDate2 = '2024-10-15'; // Extended to find more images

    // 2. Data Acquisition & Pre-processing
    // Function to mask clouds in Sentinel-2 images
    function maskS2clouds(image) {
      const qa = image.select('QA60');
      // Bits 10 and 11 are clouds and cirrus, respectively.
      const cloudBitMask = 1 << 10;
      const cirrusBitMask = 1 << 11;
      // Both flags should be set to zero, indicating clear conditions.
      const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                   .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
      return image.updateMask(mask).divide(10000)
                  .select('B.*') // Select only band data for further processing
                  .copyProperties(image, ['system:time_start']);
    }

    // Function to calculate NDWI and classify water
    function calculateWaterArea(image) {
      // Calculate NDWI = (Green - NIR) / (Green + NIR)
      const ndwi = image.normalizedDifference(['B3', 'B8']); // B3: Green, B8: NIR for S2_SR
      const waterMask = ndwi.gt(0.1); // Simple threshold for water

      // Calculate the area of water pixels
      // Scale is set to 10 for Sentinel-2 native resolution.
      const waterArea = waterMask.multiply(ee.Image.pixelArea())
                          .reduceRegion({
                            reducer: ee.Reducer.sum(),
                            geometry: geometry,
                            scale: 10,
                            maxPixels: 1e9
                          });
      return ee.Feature(null, {
        'water_area_sqm': waterArea.get('nd').aside(function(val){
          if (val === null) throw new Error('NDWI area calculation failed');
        }),
        'system:time_start': image.get('system:time_start')
      });
    }

    // Process collection for a given period
    async function getWaterExtent(startDate, endDate, periodName) {
      let collection = ee.ImageCollection('COPERNICUS/S2_SR')
                           .filterBounds(geometry)
                           .filterDate(startDate, endDate)
                           .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)); // Filter out very cloudy images

      const initialSize = await collection.size().getInfo();
      if (initialSize === 0) {
        // Fallback: try to widen the date range slightly for this period
        console.log(`No images for ${periodName} (${startDate} - ${endDate}). Widening date range.`);
        const start = ee.Date(startDate).advance(-7, 'day');
        const end = ee.Date(endDate).advance(7, 'day');
        collection = ee.ImageCollection('COPERNICUS/S2_SR')
                           .filterBounds(geometry)
                           .filterDate(start, end)
                           .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20));
        const widenedSize = await collection.size().getInfo();
        if (widenedSize === 0) {
          console.log(`No images found for ${periodName} even after widening dates.`);
          return null; // Indicates C1
        }
      }

      collection = collection.map(maskS2clouds);

      // Take the median composite to minimize cloud effects over the period
      const composite = collection.median();

      if (await composite.bandNames().size().getInfo() === 0) {
        console.log(`No valid bands in ${periodName} composite, possibly due to extreme cloud masking.`);
        return 0; // Treat as no valid pixels (C2 scenario for area calculation)
      }

      // Calculate pixel count for the composite before water classification
      const pixelCount = await composite.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geometry,
        scale: 10,
        maxPixels: 1e9
      }).values().get(0).getInfo(); // Get count of any band

      if (pixelCount === 0) {
        console.log(`No valid pixels found in ${periodName} after cloud masking.`);
        return 0; // Indicates C2
      }

      const feature = await calculateWaterArea(composite).getInfo();
      return feature.properties.water_area_sqm;
    }

    // Get water extent for Period 1
    const waterExtent1 = await getWaterExtent(startDate1, endDate1, 'Period 1 (August)');
    console.log(`Period 1 (August ${startDate1} - ${endDate1}) Water Extent: ${waterExtent1 !== null ? waterExtent1.toFixed(2) + ' sqm' : 'N/A'}`);

    if (waterExtent1 === null) {
      console.log("C1");
      return;
    }

    // Get water extent for Period 2
    const waterExtent2 = await getWaterExtent(startDate2, endDate2, 'Period 2 (September)');
    console.log(`Period 2 (September ${startDate2} - ${endDate2}) Water Extent: ${waterExtent2 !== null ? waterExtent2.toFixed(2) + ' sqm' : 'N/A'}`);

    if (waterExtent2 === null) {
      console.log("C1");
      return;
    }

    // Check for C2 scenario (no valid pixels resulting in 0 water area after processing)
    if (waterExtent1 === 0 && waterExtent2 === 0) {
      console.log("C2");
      return;
    }

    // 5. Validation & Final Answer
    if (waterExtent1 === null || isNaN(waterExtent1) || waterExtent2 === null || isNaN(waterExtent2)) {
      console.log("C3");
    } else if (waterExtent2 > waterExtent1) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (error) {
    console.error("Analysis failed:", error);
    if (error.message.includes('No such image, collection, or band') ||
        error.message.includes('Invalid argument') ||
        error.message.includes('memory')) {
      console.log("D");
    } else if (error.message.includes('NDWI area calculation failed')) {
      console.log("C3"); // Specific error for calculation failure
    } else {
      console.log("D"); // Generic error catch for unexpected issues
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
